/* Fire — TypeScript declarations for fire/fire.js (the "types" of the package "fire-design").
 *
 * HAND-WRITTEN, and guarded: scripts/test/types.test.mjs fails when a runtime export of fire/fire.js or of a module in
 * fire/js/ has no declaration, when a declared name does not exist at runtime, or when an `fd:*` event is dispatched
 * and not in FireEventMap (or the reverse). Keep it in step with fire/fire.js and the header comment of every module in
 * fire/js/: when an export, an option, an event or a detail shape changes there, change it here in the same commit.
 * Modules that fire.js does not re-export (theme, palettes, typefaces, fonts, palette-rules, initial, icons and
 * fire/email/email.js) have a sibling .d.ts that imports its types from this file.
 * IconName is the key list of ICONS in fire/js/icons.js (generated by scripts/build-icons.mjs): update it when the
 * icon set changes. The theme record (ThemeRecord, ThemeModule) follows spec/ARCHITECTURE.md section 3; the theme
 * functions live in fire/js/theme.js ("fire-design/theme"), not in fire.js.
 *
 * Only DOM lib types are used. Importing this module augments HTMLElementEventMap, ElementEventMap and
 * DocumentEventMap with FireEventMap, so `el.addEventListener('fd:change', (e) => e.detail.value)` is typed.
 */

/* ==========================================================================
   Shared vocabulary
   ========================================================================== */

/** An element, or the id of one ("dialog-id" or "#dialog-id"). Overlay and chat functions resolve it with getElementById. */
export type ElementRef = Element | string;

/** Theme setting: setTheme() and the theme toggle. */
export type FireTheme = 'light' | 'dark' | 'system';
/** data-accent values tokens.css styles (setAccent). */
export type AccentName = 'ember' | 'forest' | 'ink' | 'iris' | 'ocean' | 'volt';
/** Density: setDensity() and the tweaks dial. */
export type Density = 'compact' | 'comfortable' | 'spacious';
/** data-text-size: the tweaks dial. */
export type TextSize = 'sm' | 'md' | 'lg';
/** data-contrast: the tweaks dial. */
export type ContrastLevel = 'default' | 'high';
/** Motion dial: --fd-motion 0 · 1 · 1.75. */
export type MotionSetting = 'off' | 'default' | 'slow';
/** data-surfaces: white objects on an off-white page (default) · tinted areas without edges · drawn boxes. */
export type SurfacesSetting = 'objects' | 'flat' | 'outlined';
/** data-elevation: no shadows · today's (default) · deeper. */
export type ElevationSetting = 'none' | 'soft' | 'lifted';
/** data-controls: the secondary controls' 4% wash (default) · an edge at 3:1 · a stronger wash. */
export type ControlsSetting = 'soft' | 'outlined' | 'filled';
/** data-headings: the small labels' voice: mono capitals (default) · tracked sans capitals · mono as written. */
export type HeadingsSetting = 'sentence' | 'upper' | 'mono';
/** data-imagery: how the site's pictures are treated: as shot (default) · greyscale · ink and a tint of the accent · under an accent veil. */
export type ImagerySetting = 'natural' | 'mono' | 'duotone' | 'wash';
/** Hairline weight in px (--fd-hairline). */
export type LineWeight = 1 | 1.5 | 2;

/** Floating placement for position(), menus and popovers. */
export type Placement =
  | 'top' | 'top-start' | 'top-end'
  | 'bottom' | 'bottom-start' | 'bottom-end'
  | 'left' | 'left-start' | 'left-end'
  | 'right' | 'right-start' | 'right-end';

