/* ==========================================================================
   Chart data (fire/js/charts.js header; tones from components/charts.css)
   ========================================================================== */

/** Tone names charts.js and charts.css accept (data-tone; overrides the series slot colour). Also STRIP_TONES. */
export type ChartTone = 'neutral' | 'muted' | 'accent' | 'success' | 'warning' | 'danger' | 'info' | 'violet';
/** Named number formats of formatValue() and yFormat. */
export type ChartFormat = 'number' | 'compact' | 'percent' | 'ms' | 'credits';
/** A custom format: formatValue() calls it with the value and whether the long (tooltip/table) form is wanted. */
export type ChartFormatter = (value: number, long: boolean) => string | number;
/** Cartesian chart types (data-fd-chart). */
export type ChartType = 'line' | 'area' | 'bar' | 'stacked';

/** One series of a cartesian chart; up to 6, series 1 is the accent. */
export interface ChartSeries {
  /** Legend, tooltip and table name (default "Series n"). */
  name?: string;
  /** One value per label; null (or missing) is a gap. */
  values: Array<number | null>;
  /** Overrides the slot colour. */
  tone?: ChartTone | null;
}

/** A horizontal limit line. */
export interface ChartThreshold {
  value: number;
  /** Default "Limit: <value>". */
  label?: string;
  tone?: ChartTone | null;
}

/** Config of a cartesian chart: the JSON in <script type="application/json">, or charts.render(el, config). */
export interface ChartConfig {
  /** Chart type; defaults to data-fd-chart, else "line". */
  type?: ChartType;
  /** X tick labels ("" = no tick; thinned automatically). */
  labels?: Array<string | null>;
  /** Optional tooltip headings (default: the label). */
  titles?: string[];
  /** Up to 6 series. */
  series?: ChartSeries[];
  /** Y axis and tooltip format (default "number"). */
  yFormat?: ChartFormat | ChartFormatter;
  threshold?: ChartThreshold | null;
  /** Pulsing end-point dot on line series. */
  live?: boolean;
  /** Unit after tooltip values, e.g. "browsers". */
  unit?: string;
  /** Lower bound, or "auto" to start at the data minimum (default min(0, data)). */
  yMin?: number | 'auto';
  yMax?: number;
  /** Header of the accessible table's first column (default "Period"). */
  xTitle?: string;
  /** aria-label override. */
  label?: string;
  /** Empty-state text. */
  empty?: { title?: string; description?: string };
  /** Forced state; data-state on the element works too. */
  state?: 'loading' | 'empty';
  /** Same as state: "loading" (cleared by update() with new series or labels). */
  loading?: boolean;
  /** Plot height in px, 80–900 (default data-height, else 240). */
  height?: number;
  /** Render the built-in legend (default: the data-legend attribute). */
  legend?: boolean;
}

/** One donut segment. */
export interface DonutSegment {
  label?: string;
  value: number;
  tone?: ChartTone | null;
}

/** Donut config: the JSON inside .fd-donut. */
export interface DonutConfig {
  /** Up to 6 segments. */
  segments?: DonutSegment[];
  /** Centre figure (default: the formatted total). */
  figure?: string;
  /** Centre caption (default "Total"). */
  caption?: string;
  format?: ChartFormat | ChartFormatter;
  /** false hides the legend list. */
  legend?: boolean;
}

/** Heat grid config: one value per day from `start`, columns are weeks. */
export interface HeatgridConfig {
  /** ISO date of the first value (any weekday). */
  start?: string;
  values?: number[];
  /** Default "events". */
  unit?: string;
  summary?: string;
  label?: string;
}

/** Strip config (data-variant="strip"): one tone per day, no axis. */
export interface StripConfig {
  /** ISO date of the first point. */
  start?: string;
  /** A tone per point; null = nothing that day. */
  tones?: Array<ChartTone | null>;
  /** Names for the tones used, e.g. { success: "No problem found" }. */
  legend?: Partial<Record<ChartTone, string>>;
  /** Name of a null point (default "No data"). */
  none?: string;
  /** A point with an href is a link. */
  hrefs?: Array<string | null>;
  /** Tooltip headings (default: the day). */
  titles?: string[];
  label?: string;
  summary?: string;
}

/** One axis of a quadrant chart. */
export interface QuadrantAxis {
  /** Axis title and the name of the value in tooltips. */
  label?: string;
  /** Ends of the axis (default: the data's own range). */
  min?: number;
  max?: number;
  /** Where the dashed line cuts the axis (default: the centre). */
  mid?: number;
  /** Named format of the ticks and values (default "number"). */
  format?: ChartFormat;
}

/** One corner of a quadrant chart: its name, as text or with a tone that tints it. */
export type QuadrantCorner = string | { label: string; tone?: ChartTone | null };

/** One point of a quadrant chart. A point with an href is a link, one without is a button. */
export interface QuadrantPoint {
  name: string;
  x: number;
  y: number;
  /** Area of the dot, relative to the largest. */
  size?: number;
  /** Default: ink. */
  tone?: ChartTone | null;
  href?: string | null;
}

/** Config of a quadrant chart (data-fd-chart="quadrant"): the JSON inside the element, or charts.quadrant(el, config). */
export interface QuadrantConfig {
  type?: 'quadrant';
  x?: QuadrantAxis;
  y?: QuadrantAxis;
  corners?: { topLeft?: QuadrantCorner; topRight?: QuadrantCorner; bottomLeft?: QuadrantCorner; bottomRight?: QuadrantCorner };
  /** What the size of a point means, for the tooltip and the phone list. */
  size?: { label?: string; format?: ChartFormat };
  points?: QuadrantPoint[];
  /** aria-label override. */
  label?: string;
  empty?: { title?: string; description?: string };
  state?: 'loading' | 'empty';
  /** Plot height in px, 160–900 (default data-height, else 360). */
  height?: number;
  /** false hides the names beside the points (data-labels="none"). */
  labels?: boolean;
}

/* ==========================================================================
   Theme record (spec/ARCHITECTURE.md section 3) and the tweaks state
   ========================================================================== */

/** Preset palettes (PALETTES in fire/js/palettes.js). */
export type PaletteName =
  | 'ember' | 'volt' | 'iris' | 'ocean' | 'forest' | 'graphite' | 'rose' | 'honey' | 'plum' | 'lagoon' | 'paper'
  | 'clay' | 'mint' | 'glacier' | 'midnight';
/** Type sets (TYPEFACES in fire/js/typefaces.js). */
export type TypeSetName =
  | 'geist' | 'grotesk' | 'editorial' | 'book' | 'atelier' | 'poster' | 'terminal' | 'pixel' | 'matrix' | 'cyber'
  | 'loud' | 'gallery';

/** The named looks (LOOKS in fire/js/looks.js, from contract/looks/named). */
export type LookName = 'steady' | 'operator' | 'folio' | 'hearth' | 'instrument' | 'marquee' | 'gentle' | 'clear';

/** The colour tokens a palette sets (PALETTE_TOKENS). */
export type PaletteToken =
  | '--fd-ink' | '--fd-ink-inverse' | '--fd-wash' | '--fd-ink-wash' | '--fd-bg' | '--fd-bg-sunken' | '--fd-surface'
  | '--fd-surface-raised' | '--fd-surface-inverse' | '--fd-scrim' | '--fd-thumb' | '--fd-line-faint' | '--fd-line'
  | '--fd-line-strong' | '--fd-accent' | '--fd-accent-hover' | '--fd-accent-contrast' | '--fd-accent-text'
  | '--fd-accent-glow' | '--fd-focus' | StatusToken | ChartToken;
/** A status tone the palettes derive (STATUS_TONES). */
export type StatusTone = 'success' | 'warning' | 'danger' | 'info';
/** The status colours a palette sets (STATUS_TOKENS): solid, text, bg, line, fill and contrast of each tone. */
export type StatusToken = `--fd-${StatusTone}-${'solid' | 'text' | 'bg' | 'line' | 'fill' | 'contrast'}`;
/** The chart series a palette sets (CHART_TOKENS). */
export type ChartToken = '--fd-chart-1' | '--fd-chart-2' | '--fd-chart-3' | '--fd-chart-4' | '--fd-chart-5' | '--fd-chart-6';
/** The lines high contrast replaces (CONTRAST_TOKENS). */
export type ContrastToken = '--fd-line-faint' | '--fd-line' | '--fd-line-strong';
/** A colour in light and dark mode. */
export type LightDark = [light: string, dark: string];

/** What paletteFrom() returns: a palette in the presets' form, with the full spec it settled on and what it adjusted. */
export interface GeneratedPalette extends Palette {
  spec: PaletteFullSpec;
  notes: string[];
}

/** A palette as palettes.js produces it. */
export interface Palette {
  name: string;
  label: string;
  note: string;
  /** Every palette token as [light, dark]. */
  tokens: Record<PaletteToken, LightDark>;
  /** High-contrast line overrides. */
  contrast: Record<ContrastToken, LightDark>;
}

/** Label on the accent in a full palette spec. */
export type PaletteLabel = 'white' | 'dark' | 'inverse';
/** Neutral steps a full spec may move in L. */
export type PaletteStep = 'bg' | 'bgSunken' | 'surface' | 'raised' | 'lineFaint' | 'line' | 'lineStrong' | 'ink';

/** Palette from one accent colour. */
export interface PaletteFromAccent {
  from: 'accent';
  /** Hex accent. */
  accent: string;
  /** Neutral temperature ('tinted' takes the accent's hue), or a hue in degrees (0 to 360). */
  neutral?: 'pure' | 'cool' | 'warm' | 'tinted' | number;
  /** The label on the accent in light mode; the engine moves the accent until it is honoured. */
  on?: 'white' | 'dark';
}
/** Palette from brand colours. */
export interface PaletteFromBrand {
  from: 'brand';
  colors: string[];
}
/** The full spec form palettes.js uses internally (SPECS). */
export interface PaletteFullSpec {
  from?: undefined;
  name?: string;
  label?: string;
  note?: string;
  /** Neutral hue (OKLCH degrees). */
  hue: number;
  /** Page chroma [light, dark]; surfaces, lines and washes scale from it. */
  tint: [light: number, dark: number];
  /** Chroma and hue of the light-mode ink. */
  ink: { c: number; h?: number };
  /** [light, dark?] hex; "ink" uses the palette's own ink. */
  accent: 'ink' | [light: string, dark?: string];
  /** Label on the accent, or [light, dark]. */
  on: PaletteLabel | [light: PaletteLabel, dark: PaletteLabel];
  /** Per-step lightness overrides [light, dark] (null keeps ember's). */
  L?: { [K in PaletteStep]?: [light: number | null, dark: number | null] };
  /** Surface chroma relative to the tint in light mode. */
  surfaceTint?: number;
}
/** A palette spec: from an accent, from brand colours, or the full internal form. */
export type PaletteSpec = PaletteFromAccent | PaletteFromBrand | PaletteFullSpec;

/** Tone: bends the selected palette (ranges TONE_RANGE). */
export interface ThemeTone {
  /** −180…180°: rotates the accent group. */
  hue?: number;
  /** 0…150 %: scales the accent chroma. */
  vivid?: number;
  /** −12…12: shifts the accent's L by hundredths. */
  light?: number;
  /** −100…100: tints neutrals toward blue (−) or yellow-orange (+). */
  warmth?: number;
}
/** A complete tone, as the tweaks state holds it. */
export type Tone = Required<ThemeTone>;

/** A type set spec (theme record `type`, besides a set's name). Families come from the catalogue (fire/js/fonts.js) or
 *  are the page's own (licensed) faces. At least one of display, sans, mono; at most two families plus a mono. */
export interface TypeSpec {
  /** Heading family (--fd-font-display). */
  display?: string;
  /** Interface family (--fd-font-sans); its x-height ratio is at least 0.5 and it is not display-only. */
  sans?: string;
  /** Code family (--fd-font-mono); a mono face. */
  mono?: string;
  /** 100…900, inside the display family's weights (--fd-weight-display). */
  displayWeight?: number;
  /** −0.1…0.3 em for every heading level (--fd-ls-display, --fd-ls-h1 to -h3). */
  displayTracking?: number;
  /** 'upper' sets data-heading-case="upper". */
  headingCase?: 'sentence' | 'upper';
  /** 'tabular' sets data-figures="tabular". */
  figures?: 'proportional' | 'tabular';
}
/** The keys a TypeSpec may have (TYPE_SPEC_KEYS). */
export type TypeSpecKey = keyof TypeSpec;

/** A font family's role in the catalogue (fire/js/fonts.js). */
export type FontRole = 'display' | 'interface' | 'mono';
/** The system stack that ends a family's CSS stack. */
export type FontStack = 'sans' | 'serif' | 'mono';
/** One family of the font catalogue (FONT_FAMILIES, generated from contract/fonts.json). */
export interface FontFamily {
  stack: FontStack;
  roles: FontRole[];
  /** Never the interface face, whatever its x-height. */
  displayOnly: boolean;
  voices: string[];
  licence: string;
  variable: boolean;
  weightRange: [min: number, max: number];
  /** The weights a static family has (absent when variable). */
  weights?: number[];
  axes: string[];
  /** Ratios of the em. */
  metrics: { xHeightRatio: number; capHeightRatio: number; xWidthAvgRatio: number };
  /** The local() font and the metric overrides of its fallback face, in percent. */
  fallback: { local: string; size: number; ascent: number; descent: number; gap: number };
  /** Fire's own fire/fonts/ has the files. */
  shipped?: boolean;
  /** tokens.css declares it (and gives it no fallback). */
  core?: boolean;
}

/** The signature field names (SIGNATURE_CHOICES.field). */
export type SignatureField =
  | 'auto' | 'terrain' | 'waves' | 'orbit' | 'rain' | 'grid' | 'flame' | 'halftone' | 'spark' | 'contour' | 'stipple' | 'bars';
/** The signature mark names (MARKS, with 'auto'). */
export type SignatureMark = 'auto' | 'chars' | 'dots' | 'squares' | 'plus' | 'dashes';
/** The marks where frame bands meet the rails. */
export type SignatureMarks = 'crosses' | 'dots' | 'corners' | 'none';
/** Fire's generated texture and frame marks as one set of dials (data-signature-* on <html>, only where not the default). */
export interface ThemeSignature {
  field?: SignatureField;
  mark?: SignatureMark;
  /** 'auto' or 4…24 (the cell's width, px). */
  cell?: 'auto' | number;
  ramp?: 'auto' | RampName;
  marks?: SignatureMarks;
  /** 0.4…1.6 (default 1). */
  intensity?: number;
}

/** The dials of a theme record. */
export interface ThemeDials {
  /** 0…2, step .125 (--fd-radius-scale). */
  corners?: number;
  density?: Density;
  lines?: LineWeight;
  textSize?: TextSize;
  contrast?: ContrastLevel;
  motion?: MotionSetting;
  /** 0…1.5, step .05 (--fd-texture). */
  texture?: number;
  surfaces?: SurfacesSetting;
  elevation?: ElevationSetting;
  controls?: ControlsSetting;
  headings?: HeadingsSetting;
  imagery?: ImagerySetting;
}

/** The brand of a theme record: the shell's setBrand() input, as strings (fire/js/theme.js). */
export interface ThemeBrand {
  name?: string;
  /** A picture address for the 24px mark slot. */
  mark?: string;
  /** A wide picture that stands in for the mark and the name. */
  logo?: string;
  /** The logo for the dark scheme. */
  logoDark?: string;
  href?: string;
}

/** A product's look as one JSON record, version 1. Every field is optional (missing = Fire's default); unknown fields are an error. */
export interface ThemeRecord {
  contract?: 'fire/1';
  /** The Fire release the record was written against, such as "0.8.0". */
  fire?: string;
  palette?: PaletteName | PaletteSpec;
  tone?: ThemeTone;
  type?: TypeSetName | TypeSpec;
  dials?: ThemeDials;
  signature?: ThemeSignature;
  brand?: ThemeBrand;
}

/** expandTheme() result. */
export interface ExpandedTheme {
  /** Token name → [light, dark] or one value. */
  tokens: Record<string, [string, string] | string>;
  /** Attributes for <html>, e.g. { 'data-palette': …, 'data-density': … }. */
  attributes: Record<string, string>;
  /** Fallback @font-face rules for the families of a type spec. */
  faces: string[];
  /** What the engine adjusted. */
  notes: string[];
  /** The record's brand, untouched (a brand is not CSS; tweaks.set() hands it to setBrand()). */
  brand?: ThemeBrand;
}

/** validateTheme() result. */
export interface ThemeValidation {
  ok: boolean;
  errors: string[];
  /** What Fire cannot check (a family outside the catalogue, a font the page must load). */
  notes: string[];
}

/** The tweaks state (tweaks.get()). */
export interface TweaksState {
  palette: PaletteName;
  type: TypeSetName;
  tone: Tone;
  theme: FireTheme;
  density: Density;
  corners: number;
  lines: LineWeight;
  textSize: TextSize;
  contrast: ContrastLevel;
  motion: MotionSetting;
  texture: number;
  surfaces: SurfacesSetting;
  elevation: ElevationSetting;
  controls: ControlsSetting;
  headings: HeadingsSetting;
  imagery: ImagerySetting;
  signature: Required<ThemeSignature>;
}
