/** Toast tones. */
export type ToastTone = 'neutral' | 'success' | 'danger' | 'warning' | 'info' | 'loading';
/** toast() options. */
export interface ToastOptions {
  title?: string;
  description?: string;
  tone?: ToastTone;
  /** Overrides the tone's icon. */
  icon?: IconName;
  /** An action button; returning false from onClick keeps the toast. */
  action?: { label: string; onClick?: (event: MouseEvent, id: string) => boolean | void };
  /** ms; Infinity persists (default 5000, danger 8000, loading Infinity). */
  duration?: number;
  /** Reusing an id updates that toast. */
  id?: string;
  /** false hides the close button. */
  dismissible?: boolean;
  onDismiss?: (id: string) => void;
  /** "Done · Undo": adds an Undo action and lasts 8 seconds. The function runs when Undo is pressed (the button is
   *  busy meanwhile); then fd:undo fires on the toast and it turns into "Undone". A rejection turns it into a danger
   *  toast with the error's message. */
  undo?: () => unknown | Promise<unknown>;
  /** The title after an undo (default "Undone"; label toast.undone). */
  undone?: string;
  /** The description after an undo. */
  undoneDescription?: string;
}
/** toast.hold() options: a toast that counts down beside Undo before anything happens. */
export interface ToastHoldOptions extends ToastOptions {
  /** Countdown length (default 10, at least 1). */
  seconds?: number;
  /** Where fd:hold, fd:undo and fd:commit fire (default: the toast); an element that is gone falls back to the toast. */
  target?: Element | null;
  /** Merged into the detail of those events, with `toast` (the id). */
  detail?: Record<string, unknown>;
  /** The time ran out (cause "time") or the page was left ("pagehide"). */
  onCommit?: (id: string, cause: 'time' | 'pagehide') => void;
  /** Undo was pressed. */
  onUndo?: (id: string) => void;
}
/** A toast.promise() message: a title, options, or a function of the settled value. */
export type ToastMessage<V> = string | ToastOptions | ((value: V) => string | ToastOptions | null | undefined);
/** The toast function and its helpers. */
export interface ToastFunction {
  /** Show a toast; returns its id. */
  (input?: ToastOptions | string): string;
  /** Dismiss one toast, or every toast with no id. */
  dismiss(id?: string): void;
  /** A held toast: the ring counts down beside Undo, nothing has happened yet. Cancel fd:commit to keep the toast as a loading toast. Returns the id. */
  hold(options?: ToastHoldOptions): string;
  /** Patch a toast (shows it when the id is unknown); returns the id. */
  update(id: string, patch?: ToastOptions): string;
  success(title: string, options?: ToastOptions): string;
  danger(title: string, options?: ToastOptions): string;
  error(title: string, options?: ToastOptions): string;
  warning(title: string, options?: ToastOptions): string;
  info(title: string, options?: ToastOptions): string;
  /** A loading toast that turns into success or danger when the promise settles; returns its id. */
  promise<T>(
    promise: Promise<T> | (() => Promise<T>),
    messages?: { loading?: ToastMessage<void>; success?: ToastMessage<T>; error?: ToastMessage<unknown> },
  ): string;
}

